INSERT INTO cases VALUES(38,'TX-26-01376','44th District Court','GINSBERG, CARL','2026-07-06','OPEN','TAX DELINQUENCY','Juan Fernando Gonzalez','[{"name": "Juan Fernando Gonzalez", "address": "3307 Fordham Rd., Dallas, TX 75216-4824", "serviceStatus": "unserved", "serviceMethod": "Private Process Server", "isInRemOnly": false, "notes": "In Personam defendant; citation issued 07/07/2026"}, {"name": "Graciela Janet Hernandez", "address": "3307 Fordham Rd., Dallas, TX 75216-4824", "serviceStatus": "unserved", "serviceMethod": "Private Process Server", "isInRemOnly": false, "notes": "In Personam defendant; citation issued 07/07/2026"}, {"name": "Micaela Acosta", "address": "630 Delaware Avenue, Dallas, TX 75208", "serviceStatus": "unserved", "serviceMethod": "Private Process Server", "isInRemOnly": true, "notes": "In Rem Only; citation issued 07/07/2026"}, {"name": "Jose Acosta", "address": "630 Delaware Avenue, Dallas, TX 75208", "serviceStatus": "unserved", "serviceMethod": "Private Process Server", "isInRemOnly": true, "notes": "In Rem Only; citation issued 07/07/2026"}]','3307 Fordham Road, Dallas, TX 75216-4824',NULL,'00000510040000000','LGBS (Linebarger)','Pamela Pope Lee',18013.349999999999084,2017,'[2017, 2018, 2019, 2021, 2022, 2023, 2024, 2025]',4,0,0,'[]',0,0,0,'All 4 defendants unserved as of docket; citations issued 07/07/2026 via private process server','medium',NULL,NULL,'none',NULL,0,'2027-03-01',NULL,NULL,NULL,'dallas',NULL,'[{"entity": "Dallas County", "taxAmt": 938.06, "penaltyInterest": 690.25, "total": 1628.31}, {"entity": "Parkland Hospital District", "taxAmt": 982.86, "penaltyInterest": 742.43, "total": 1725.29}, {"entity": "Dallas College", "taxAmt": 480.2, "penaltyInterest": 356.96, "total": 837.16}, {"entity": "Dallas County School Equalization Fund", "taxAmt": 20.55, "penaltyInterest": 20.86, "total": 41.41}, {"entity": "Dallas Independent School District", "taxAmt": 4753.16, "penaltyInterest": 3628.59, "total": 8381.75}, {"entity": "City of D